1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUM_RATES: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	const LOYALTY_YEARS_THRESHOLD = 2;
58	const LOYALTY_DISCOUNT_RATE = 0.2;
59	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
60	const COMPONENT_BLOCK_SIZE = 3;
61	const COMPONENT_BLOCK_PREMIUM = 60;
62	
63	const countByType = (items: Item[]): Map<string, number> =>
64	  items.reduce(
65	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
66	    new Map<string, number>(),
67	  );
68	
69	const basePremiumForGroup = (type: string, itemCount: number): number =>
70	  itemCount === COMPONENT_BLOCK_SIZE
71	    ? COMPONENT_BLOCK_PREMIUM
72	    : itemCount * BASE_PREMIUM_RATES[type];
73	
74	// The policy base premium: the sum of all item base premiums, EXCLUDING
75	// item-specific surcharges. Policy-wide modifiers are percentages of this.
76	const policyBasePremium = (items: Item[]): number =>
77	  [...countByType(items)].reduce(
78	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
79	    0,
80	  );
81	
82	const itemSurchargeRate = (item: Item): number =>
83	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
84	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
85	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
86	    : 0);
87	
88	const sumItemSurcharges = (items: Item[]): number =>
89	  items.reduce(
90	    (sum, item) => sum + BASE_PREMIUM_RATES[item.type] * itemSurchargeRate(item),
91	    0,
92	  );
93	
94	// Premiums round in the MHPCO's favor, i.e. up.
95	const roundPremiumInMHPCOsFavor = (premium: number): number =>
96	  Math.ceil(premium);
97	
98	// Each policy-wide modifier is a signed percentage of the policy base premium:
99	// surcharges positive, discounts negative.
100	const policyWideModifierRates = (
101	  customer: Customer,
102	  precedingQuoteCount: number,
103	): number[] => [
104	  FIRST_INSURANCE_SURCHARGE_RATE,
105	  ...(customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
106	    ? [-LOYALTY_DISCOUNT_RATE]
107	    : []),
108	  ...(precedingQuoteCount > 0 ? [-FOLLOW_UP_CONTRACT_DISCOUNT_RATE] : []),
109	];
110	
111	// Each rate is multiplied out against the base premium SEPARATELY and then
112	// summed. Summing the rates first and doing a single multiply is algebraically
113	// equal but not equal in floating point — 100 * (1 + 0.1) is 110.00000000000001
114	// — and rounding up turns that into a spurious extra gold piece.
115	const sumPolicyWideModifiers = (
116	  basePremium: number,
117	  customer: Customer,
118	  precedingQuoteCount: number,
119	): number =>
120	  policyWideModifierRates(customer, precedingQuoteCount).reduce(
121	    (sum, rate) => sum + basePremium * rate,
122	    0,
123	  );
124	
125	const quote = (
126	  items: Item[],
127	  customer: Customer,
128	  precedingQuoteCount: number,
129	): StepResult => {
130	  const basePremium = policyBasePremium(items);
131	
132	  return {
133	    premium: roundPremiumInMHPCOsFavor(
134	      basePremium +
135	        sumItemSurcharges(items) +
136	        sumPolicyWideModifiers(basePremium, customer, precedingQuoteCount) +
137	        PROCESSING_FEE,
138	    ),
139	  };
140	};
141	
142	const runStep = (
143	  step: Step,
144	  customer: Customer,
145	  precedingQuoteCount: number,
146	): StepResult => {
147	  switch (step.op) {
148	    case "quote":
149	      return quote(step.items, customer, precedingQuoteCount);
150	    default:
151	      throw new Error(`Unsupported step: ${step.op}`);
152	  }
153	};
154	
155	export const runScenario = (scenario: Scenario): ScenarioResult => {
156	  let precedingQuoteCount = 0;
157	  const results = scenario.steps.map((step) => {
158	    const result = runStep(step, scenario.customer, precedingQuoteCount);
159	    if (step.op === "quote") precedingQuoteCount += 1;
160	
161	    return result;
162	  });
163	
164	  return { results };
165	};
