119	// summed. Summing the rates first and doing a single multiply is algebraically
120	// equal but not equal in floating point — 100 * (1 + 0.1) is 110.00000000000001
121	// — and rounding up turns that into a spurious extra gold piece.
122	const sumPolicyWideModifiers = (
123	  basePremium: number,
124	  context: QuoteContext,
125	): number =>
126	  policyWideModifierRates(context).reduce(
127	    (sum, rate) => sum + basePremium * rate,
128	    0,
129	  );
130	
131	const quote = (items: Item[], context: QuoteContext): StepResult => {
132	  const basePremium = policyBasePremium(items);
133	
134	  return {
135	    premium: roundPremiumInMHPCOsFavor(
136	      basePremium +
137	        sumItemSurcharges(items) +
138	        sumPolicyWideModifiers(basePremium, context) +
139	        PROCESSING_FEE,
140	    ),
141	  };
142	};
143	
144	const runStep = (step: Step, context: QuoteContext): StepResult => {
145	  switch (step.op) {
146	    case "quote":
147	      return quote(step.items, context);
148	    default:
149	      throw new Error(`Unsupported step: ${step.op}`);
150	  }
151	};
152	
153	export const runScenario = (scenario: Scenario): ScenarioResult => {
154	  let precedingQuoteCount = 0;
155	  const results = scenario.steps.map((step) => {
156	    const result = runStep(step, {
157	      customer: scenario.customer,
158	      precedingQuoteCount,
159	    });
160	    if (step.op === "quote") precedingQuoteCount += 1;
161	
162	    return result;
163	  });
164	
165	  return { results };
